local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a70eb060dd7e325e"] = { "<Caro/Cara> <ragazzo/ragazza>, sei <arrivato/arrivata> giusto in tempo per aiutare la Kargath Expeditionary Force.", "." },
  ["a71009919b945413"] = { "Trovatemi qualcosa di buono, cani!", "." },
  ["a71bb7efd79a0f6f"] = { "Abbiamo vinto $2219W battaglie contro il Flagello. Coraggio, {name}. Anche se ci attendono molte battaglie, eroi di ogni reame si sono levati per combatterle.", "." },
  ["a72659562c67bee0"] = { "%s abbassa le spalle e scopre il collo.", "." },
  ["a72767537355b96e"] = { "%s emette un lungo, interminabile sospiro.", "." },
  ["a72a6be135dce4ba"] = { "Ti distruggerò...", "." },
  ["a736441c346a2ef4"] = { "Tutti ai posti di combattimento! Arrivano i naga!", "." },
  ["a7370b86067de9ff"] = { "Il Forte di ⟦Nethergarde=Guardiafatua⟧ ha sempre bisogno di altre provviste: provviste per aiutare i nostri maghi nelle loro ricerche, e provviste per tenere i nostri difensori in perfetta forma per combattere.", "." },
  ["a737bdadcacfef5c"] = { "Fammi installare questi Ingranaggi Giromeccanici e Ingranaggi Stabilizzatori, e poi accendiamo il Recombobulator.", "." },
  ["a747f3db4f0edd9d"] = { "Grazie, {name}. Che la Luce ti benedica, <fratello/sorella>, e guidi il tuo cammino.", "." },
  ["a748415fa65fae51"] = { "Barnil, mi sa che ho perso il Capitolo I.", "." },
  ["a7533681c2c3ed25"] = { "Vuoi imparare a usare un'arma, eh? Be', non startene lì a bocca aperta, parla, <ragazzo/ragazza>!", "." },
  ["a7538374408b1397"] = { "{name}, che la tua morte sia d'esempio per chiunque sfidi la ⟦Defias Brotherhood=Fratellanza dei Defias⟧!", "." },
  ["a7541e6cfcf72454"] = { "Salute, <ragazzo/ragazza>! Se cerchi i migliori affari che troverai fuori da ⟦Ironforge=Forgiardente⟧, sei nel posto giusto.", "." },
  ["a76369b6780171b0"] = { "Chiedo scusa, Pebblebitty.", "." },
  ["a7690c3491d0a9c9"] = { "Ah, sei tu che hai trovato la lettera. Grazie per le... notizie, credo, sulla mia famiglia. Prendi pure il cibo e le bevande che posso offrirti.", "." },
  ["a76edb220f4b59d3"] = { "Sei <un/una> <cacciatore/cacciatrice>? Be', comunque, troverai Thotar al riparo dal sole dentro la tana nell'angolo sud-ovest del paese.", "." },
  ["a77684f31a558c83"] = { "%s si inchina.", "." },
  ["a77725eef2ea5d43"] = { "Ci vuole un po' di pratica per stare così vicino ai silitidi senza farsi notare. Non ti consiglio di provarci, se puoi evitarlo.", "." },
  ["a7804370b0274f1e"] = { "Ecco fatto, ce l'abbiamo fatta! Il rituale è avviato, e i fuochi dell'idolo stanno per spegnersi per sempre! Siete davvero gli eroi che speravo!", "." },
  ["a783e6d8ab47a6f7"] = { "Throm'ka, {class}. Sei qui per aiutarmi con i Lingotti di Stagno? Mi dicono che me ne serviranno $2006w per fare armi e armature per l'imminente Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧, ma per ora ne ho solo $2005w. Me ne porterai altri!", "." },
  ["a78a8947d4203cda"] = { "CIAO MONDO!", "." },
  ["a799a74b1497f509"] = { "Nonostante la loro tragedia, i Non Morti sono venuti fin qui per aiutarci. Spero solo che noi possiamo essere altrettanto utili a loro. Cerca padre Otium vicino alle Pozze delle Visioni, sotto l'⟦Spirit Rise=Altura degli Spiriti⟧.", "." },
  ["a7a542dd2d607b7d"] = { "Siediti e ascolta la mia storia, {race}.", "." },
  ["a7a93c5872661fa2"] = { "Quale saggezza posso trasmetterti?", "." },
  ["a7ab4c8f3c0ff8d6"] = { "È così che si fa, classe! Fareste meglio a stare attenti!", "." },
  ["a7ac0ebc77c0e5a8"] = { "Le nostre unità campione sono equipaggiate! Trema, Alleanza!", "." },
  ["a7b384d672c0bce2"] = { "Avanti! Il fronte ci aspetta!", "." },
  ["a7b76a8343a59492"] = { "Le ⟦Burning Steppes=Steppe Ardenti⟧ sono sotto attacco in questo momento?", "." },
  ["a7b901b39fdddc68"] = { "I segreti di Elune sono molti, ma non vanno condivisi con chiunque.", "." },
  ["a7bc0efdbea0836f"] = { "Non sembra essere stata affatto una sfida. Vediamo come te la cavi con la seconda prova. Lysta, fa' avanzare i servitori del Re dei Lich.", "." },
  ["a7bd9ab46177e972"] = { "La ⟦Scarlet Crusade=Crociata Scarlatta⟧ spazzerà via tutto da queste terre!", "." },
  ["a7be1464a80c6879"] = { "Esatto, siamo stupidi. Stupidi come una volpe!", "." },
  ["a7c64da4be4b5458"] = { "Già, e che campo di battaglia vai cercando?", "." },
  ["a7c8b82cdf561536"] = { "<Benvenuto/Benvenuta> al fronte, {class}. Il Regno di ⟦Stormwind=Roccavento⟧, con l'aiuto dei suoi alleati, mi ha mandato qui a contrastare la minaccia crescente del Flagello. Qui alla ⟦Chillwind Point=Gola di Ventofreddo⟧ combattiamo ogni giorno per la nostra sopravvivenza.\n\nSe sei <venuto/venuta> a cercare l'occasione di dimostrarti <un/una> <eroe/eroina>, qui ne troverai in abbondanza... soprattutto ora che avanziamo verso Andorhal e la forza maligna che controlla il Flagello laggiù.", "." },
  ["a7cc380126b8b9e3"] = { "Rin'ji è libero!", "." },
  ["a7cc3ddb1608e68b"] = { "Altre... Altre anime!", "." },
  ["a7d97ecc9ce6ebd2"] = { "Potrei schiacciarti con un solo gesto. Non farmi arrabbiare.", "." },
  ["a7df633f33cabb17"] = { "Ti proteggerò!", "." },
  ["a7e43f7f54017b91"] = { "Porterò i miei segreti nella tomba!", "." },
  ["a7f44b02d464df80"] = { "Ti stavo aspettando, {name}.", "." },
  ["a7f951d6c8079f5b"] = { "Ah, che bello liberarsi dalle catene! Hai già liberato Tog'thar? Gli umani ci hanno separati dopo la cattura.", "." },
})
